// product.interface.ts
export interface Product {
  id: number;
  name: string;
  price: number;
}

// product-list.component.ts
import { Component } from '@angular/core';
import { Product } from './product.interface';

@Component({
  selector: 'app-product-list',
  templateUrl: './product-list.component.html'
})
export class ProductListComponent {
  products: Product[] = [
    { id: 1, name: 'Laptop', price: 999 },
    { id: 2, name: 'Mouse', price: 29 },
    { id: 3, name: 'Keyboard', price: 79 },
    { id: 4, name: 'Monitor', price: 299 },
    { id: 5, name: 'Webcam', price: 49 }
  ];

  trackById(index: number, product: Product): number {
    return product.id;
  }

  shuffle() {
    // Create a new array with the same items in random order
    this.products = [...this.products].sort(() => Math.random() - 0.5);
  }
}

// product-list.component.html
<button (click)="shuffle()">Shuffle</button>
<ul>
  <li *ngFor="let product of products; let i = index; let isEven = even; trackBy: trackById"
      [style.background]="isEven ? '#f0f0f0' : 'white'">
    {{ i + 1 }}. {{ product.name }} - ${{ product.price }}
  </li>
</ul>
